/**
 * Applies the user's tier discount to the cart and awards a loyalty point.
 *
 * Mutates both arguments: sets `subtotal` on each cart item, scales
 * `cart.total` in place, and increments `user.points`.
 *
 * Note: `cart.total` is not recomputed from the item subtotals, so it must
 * already be up to date when this is called. Calling this twice on the same
 * cart applies the discount (and awards a point) twice.
 *
 * @param {{ items: Array<{ price: number, quantity: number }>, total: number }} cart
 * @param {{ points: number, tier: string }} user
 * @returns The same `cart` object, for chaining.
 */
function applyDiscount(cart, user) {
  user.points += 1;

  for (const item of cart.items) {
    item.subtotal = item.price * item.quantity;
  }

  // TODO: handle expired coupons
  if (user.tier === 'gold') {
    // Gold tier gets 10% off the cart total.
    cart.total *= 0.9;
  }
  return cart;
}
```

